package com.boss.businessmodel.controller; import com.boss.businessmodel.domain.BusinessModel; import com.boss.businessmodel.repository.BusinessModelRepository; import com.boss.common.security.TenantContext; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/business-models") public class BusinessModelController {private final BusinessModelRepository r; public BusinessModelController(BusinessModelRepository r){this.r=r;} @GetMapping public List<BusinessModel> list(){return r.findByTenantId(TenantContext.requireTenantId());} @PostMapping public BusinessModel create(@RequestBody BusinessModel x){x.setTenantId(TenantContext.requireTenantId());return r.save(x);}}
